    },
    {
      "principle": "Learning and autonomy",
      "turn": 1,
      "quote": "What's up to you is what you do in your own house.",
      "use": "correct",
      "note": "It recognizes the user's decision-making role; its invitation to provide more context also leaves room to learn rather than treating its view as final."
    },
    {
      "principle": "Loyalty and authority",
